import{c as s,Q as e,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const p="/assets/CPU%E5%9F%9F%E5%92%8CNPU%E5%9F%9F%E7%9A%84%E6%A0%B8%E5%87%BD%E6%95%B0%E8%BF%90%E8%A1%8C%E9%80%BB%E8%BE%91%E5%AF%B9%E6%AF%94.D43fjEmo.png",h=JSON.parse('{"title":"CPU域孪生调试","description":"","frontmatter":{},"headers":[{"level":1,"title":"CPU域孪生调试","slug":"cpu域孪生调试"},{"level":2,"title":"CPU侧验证核函数","slug":"cpu侧验证核函数"},{"level":2,"title":"gdb调试","slug":"gdb调试"},{"level":2,"title":"使用printf打印命令打印","slug":"使用printf打印命令打印"}],"relativePath":"guide/编程指南/调试调优/功能调试/CPU域孪生调试.md","filePath":"guide/编程指南/调试调优/功能调试/CPU域孪生调试.md"}'),l={name:"guide/编程指南/调试调优/功能调试/CPU域孪生调试.md"};function i(o,a,c,r,d,g){return e(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="cpu域孪生调试" tabindex="-1">CPU域孪生调试 <a class="header-anchor" href="#cpu域孪生调试" aria-label="Permalink to &quot;CPU域孪生调试&quot;">​</a></h1><p>本节介绍CPU域调试的方法：CPU侧验证核函数，gdb调试、使用printf命令打印。当前SIMT编程场景不支持。</p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>CPU调测过程中，配置日志相关环境变量，可以记录程序的运行过程及异常信息，有助于开发者进行功能调测。 关于环境变量的使用约束以及详细说明，可参见<a href="https://www.hiascend.com/document/redirect/CannCommunityEnvRef" target="_blank" rel="noreferrer">《环境变量参考》</a>中“辅助功能 &gt; 日志”章节。</p></div><h2 id="cpu侧验证核函数" tabindex="-1">CPU侧验证核函数 <a class="header-anchor" href="#cpu侧验证核函数" aria-label="Permalink to &quot;CPU侧验证核函数&quot;">​</a></h2><p>在非昇腾设备上，开发者可以利用CPU仿真环境先行进行算子开发和测试，并在准备就绪后，利用昇腾设备进行加速计算。在<a href="./../../编译与运行/编译与运行.html">编译与运行</a>章节，我们已经介绍了算子Kernel程序NPU域的编译运行。相比于NPU域的算子运行逻辑，CPU域调试将算子Kernel程序以Host程序的形式进行编译，此时算子Kernel程序链接CPU调测库，执行编译生成的可执行文件，可以完成算子CPU域的运行验证。CPU侧的运行程序，通过GDB通用调试工具进行单步调试，可以精准验证程序执行流程是否符合预期。</p><p><strong>图 1</strong> CPU域和NPU域的核函数运行逻辑对比<br><img src="'+p+`" alt="" title="CPU域和NPU域的核函数运行逻辑对比"></p><p>推荐使用CMake编译方式，可在最小化修改的情况下快速开启CPU域孪生调试功能。</p><ol><li><p>启用CPU域调试需包含&quot;cpu_debug_launch.h&quot;头文件。</p><p>bisheng编译器在CPU调试模式下会对&lt;&lt;&lt;&gt;&gt;&gt;调用核函数的过程进行转义，实现核函数在CPU域下的调用，相关调用函数定义在&quot;cpu_debug_launch.h&quot;中，在使用&lt;&lt;&lt;&gt;&gt;&gt;语法调用核函数的源文件中，请通过以下方式包含必需的头文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifdef ASCENDC_CPU_DEBUG</span></span>
<span class="line"><span>#include &quot;cpu_debug_launch.h&quot;</span></span>
<span class="line"><span>#endif</span></span></code></pre></div></li><li><p>通过在CMake配置阶段传入变量CMAKE_ASC_RUN_MODE和CMAKE_ASC_ARCHITECTURES即可开启CPU域编译。命令示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake -B build -DCMAKE_ASC_RUN_MODE=cpu -DCMAKE_ASC_ARCHITECTURES=dav-2201</span></span></code></pre></div><p>cpu表示开启CPU域编译，dav-后为NPU架构版本号，请根据实际情况参考<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">对应关系表</a>进行填写。</p><p>其他CMakeLists.txt项目配置<a href="./../../编译与运行/AI-Core-SIMD编译/通过CMake编译.html">通过CMake编译</a>进行编写。</p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>为了实现CPU域与NPU域代码归一，框架在CPU域中仅对部分acl接口进行适配，开发者在使用CPU域调测功能时，仅支持使用如下acl接口，并且不支持用户自行链接<strong>ascendcl库</strong>：</p><ul><li>有实际功能接口，支持CPU域调用 <ul><li>aclDataTypeSize、aclFloat16ToFloat、aclFloatToFloat16。</li><li>aclrtMalloc、aclrtFree、aclrtMallocHost、aclrtFreeHost、aclrtMemset、aclrtMemsetAsync、aclrtMemcpy、aclrtMemcpyAsync、aclrtMemcpy2d、aclrtMemcpy2dAsync、aclrtCreateContext、aclrtDestroyContext。</li></ul></li><li>无实际功能接口，打桩实现。 <ul><li>Profiling数据采集 aclprofInit、aclprofSetConfig、aclprofStart、aclprofStop、aclprofFinalize。</li><li>系统配置 aclInit、aclFinalize、aclrtGetVersion。</li><li>运行时管理 aclrtSetDevice、aclrtResetDevice、aclrtCreateStream、aclrtCreateStreamWithConfig、aclrtDestroyStream、aclrtDestroyStreamForce、aclrtSynchronizeStream、aclrtCreateContext、aclrtDestroyContext。</li></ul></li></ul></div><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p>在CPU孪生调试模式下，编译器不识别Ascend C提供的<a href="./../../语言扩展层/SIMD-BuiltIn关键字.html">SIMD-BuiltIn关键字</a>及<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html">SIMT-BuiltIn关键字</a>，包括</p><ul><li><strong>函数执行空间限定符</strong>：如 <code>__aicore__</code>、<code>__global__</code>、<code>__host__</code> 等;</li><li><strong>函数标记宏</strong>：如 <code>__simd_vf__</code>、<code>__simd_callee__</code>、<code>__simt_vf__</code> 等；</li><li><strong>地址空间限定符</strong>：如 <code>__gm__</code> 、<code>__ubuf__</code> 等。</li></ul><p>这些关键字与 Device 侧执行强相关，在 CPU 孪生调试模式下无需实际生效，因此系统框架将这些关键字定义为空。 由于这种置空处理，<strong>仅通过BuiltIn关键字区分的函数签名将被视为相同</strong>，会导致重定义编译错误。</p><p>典型问题场景包括：</p><ol><li><strong>Device侧函数与Host侧函数同名</strong></li></ol><p>&lt;blockquote&gt; 如下例中，<code>add</code> 函数仅通过 <code>__aicore__</code> 区分运行域，在 CPU 孪生调试模式下两个声明将冲突： &lt;pre&gt;&lt;code class=&quot;language-asc&quot;&gt;<strong>aicore</strong> inline void add(int x, int y); // Device侧 void add(int x, int y); // Host侧（等同于 <strong>host</strong>）&lt;/code&gt;&lt;/pre&gt; &lt;/blockquote&gt;</p><ol start="2"><li><strong>参数类型仅有地址空间限定符不同</strong></li></ol><p>&lt;blockquote&gt; 如下例中，两个Device侧函数仅在指针的地址空间限定符上不同： &lt;pre&gt;&lt;code class=&quot;language-asc&quot;&gt;<strong>aicore</strong> inline void process(<strong>gm</strong> void* data, int size); <strong>aicore</strong> inline void process(<strong>ubuf</strong> void* data, int size); &lt;/code&gt;&lt;/pre&gt; &lt;/blockquote&gt;</p><p><strong>在孪生调试场景下需特别注意</strong>：请勿定义仅依赖BuiltIn关键字来区分的函数。</p></div><h2 id="gdb调试" tabindex="-1">gdb调试 <a class="header-anchor" href="#gdb调试" aria-label="Permalink to &quot;gdb调试&quot;">​</a></h2><p>可使用<strong>gdb</strong>单步调试算子计算精度。由于cpu调测已转为多进程调试，每个核都会拉起独立的子进程，故gdb需要转换成子进程调试的方式。针对耦合架构，每个AI Core会拉起1个子进程。针对分离架构，默认每个AI Core会拉起3个子进程，1个Cube，2个Vector。</p><ul><li><p>调试单独一个子进程</p><p>启动gdb，示例中的add_custom_cpu为CPU域的算子可执行文件，参考<a href="./../../附录/基于样例工程完成Kernel直调.html#section188001652105215">修改并执行一键式编译运行脚本</a>，将一键式编译运行脚本中的run-mode设置成cpu，即可编译生成CPU域的算子可执行文件。</p><p>gdb启动后，首先设置跟踪子进程，之后再打断点，就会停留在子进程中，但是这种方式只会停留在遇到断点的第一个子进程中，其余子进程和主进程会继续执行直到退出。涉及到核间同步的算子无法使用这种方法进行调试。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb --args add_custom_cpu  // 启动gdb，add_custom_cpu为算子可执行文件</span></span>
<span class="line"><span>(gdb) set follow-fork-mode child</span></span></code></pre></div></li><li><p>调试多个子进程</p><p>如果涉及到核间同步，那么需要能同时调试多个子进程。</p><p>在gdb启动后，首先设置调试模式为只调试一个进程，挂起其他进程。设置的命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) set detach-on-fork off</span></span></code></pre></div><p>查看当前调试模式的命令为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) show detach-on-fork</span></span></code></pre></div><p>中断gdb程序要使用捕捉事件的方式，即gdb程序捕捉fork这一事件并中断。这样在每一次起子进程时就可以中断gdb程序。设置的命令为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) catch fork</span></span></code></pre></div><p>当执行r后，可以查看当前的进程信息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info inferiors</span></span>
<span class="line"><span>  Num  Description</span></span>
<span class="line"><span>* 1    process 19613</span></span></code></pre></div><p>可以看到，当第一次执行fork的时候，程序断在了主进程fork的位置，子进程还未生成。</p><p>执行c后，再次查看info inferiors，可以看到此时第一个子进程已经启动。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) info inferiors</span></span>
<span class="line"><span>  Num  Description </span></span>
<span class="line"><span>* 1    process 19613</span></span>
<span class="line"><span>  2    process 19626</span></span></code></pre></div><p>这个时候可以使用切换到第二个进程，也就是第一个子进程，再打上断点进行调试，此时主进程是暂停状态：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(gdb) inferior 2</span></span>
<span class="line"><span>[Switching to inferior 2 [process 19626] ($HOME/demo)]</span></span>
<span class="line"><span>(gdb) info inferiors</span></span>
<span class="line"><span>  Num  Description</span></span>
<span class="line"><span>  1    process 19613</span></span>
<span class="line"><span>* 2    process 19626</span></span></code></pre></div><p>请注意，inferior后跟的数字是进程的序号，而不是进程号。</p><p>如果遇到同步阻塞，可以切换回主进程继续生成子进程，然后再切换到新的子进程进行调试，等到同步条件完成后，再切回第一个子进程继续执行。</p></li></ul><p>如下是调试一个单独子进程的命令样例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gdb --args add_custom_cpu</span></span>
<span class="line"><span>set follow-fork-mode child</span></span>
<span class="line"><span>break add_custom.cpp:45</span></span>
<span class="line"><span>run</span></span>
<span class="line"><span>list</span></span>
<span class="line"><span>backtrace</span></span>
<span class="line"><span>print i</span></span>
<span class="line"><span>break add_custom.cpp:56</span></span>
<span class="line"><span>continue</span></span>
<span class="line"><span>display xLocal</span></span>
<span class="line"><span>quit</span></span></code></pre></div><h2 id="使用printf打印命令打印" tabindex="-1">使用printf打印命令打印 <a class="header-anchor" href="#使用printf打印命令打印" aria-label="Permalink to &quot;使用printf打印命令打印&quot;">​</a></h2><p>在代码中直接编写printf(...)来观察数值的输出。样例代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>printf(&quot;xLocal size: %d\\n&quot;, xLocal.GetSize()); </span></span>
<span class="line"><span>printf(&quot;tileLength: %d\\n&quot;, tileLength);</span></span></code></pre></div>`,18)])])}const b=s(l,[["render",i]]);export{h as __pageData,b as default};
